import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long x = sc.nextLong();
        long y = sc.nextLong();
        long n = sc.nextLong();
        double ratio = (double) x / (double) y;
        long bestA = 0;
        long bestB = 1;
        double minError = Double.MAX_VALUE;

        for (long b = 1; b <= n; b++) {
            double val = ratio * b;
            long a1 = (long) val;
            long a2 = a1 + 1;

            double error1 = Math.abs(ratio - (double) a1 / b);
            double error2 = Math.abs((double) a2 / b - ratio);

            if (error1 < minError) {
                minError = error1;
                bestA = a1;
                bestB = b;
            }
            if (error2 < minError) {
                minError = error2;
                bestA = a2;
                bestB = b;
            }
        }
        System.out.println(bestA + "/" + bestB);
    }
}
